import io
import os
import random
import struct
from typing import List

# Assumptions about libfive serialized tree format
# -------------------------------------------------
# The real libfive on-disk format is non-archival and not documented here.
# However, libfive can print and read Scheme-like S-expressions, and many
# builds support loading textual tree descriptions (as produced by save/print).
# We'll generate a UTF-8 textual representation that typical libfive builds
# accept when loading, focusing on a variety of nodes: constants, variables,
# coordinates, unary and binary ops, remapping-like compositions, and nested
# expressions. The data will be valid UTF-8 and under 4096 bytes.
#
# Strategy:
# - Build a small DSL of expressions using common libfive op names
#   such as + - * / min max pow sin cos tan abs floor ceil sqrt atan2
# - Include constants, x y z, and free variables (var) to exercise handling
#   of variables even if they default to 0 in some evaluation paths.
# - Produce different trees seeded with the provided seed, ensuring repeatable
#   yet varied outputs.
# - Wrap as a single S-expression tree string terminated by a newline.
#
# If a particular build expects a binary format, it will likely reject the
# input. But many builds accept textual S-expressions, so generating those
# increases the chance of successful deserialization.


COORDS = ["x", "y", "z"]
UNARY_OPS = [
    "neg",  # arithmetic negation
    "sin", "cos", "tan",
    "abs", "sqrt",
    "exp", "log",
    "floor", "ceil",
]
BINARY_OPS = [
    "+", "-", "*", "/",
    "min", "max",
    "pow",
    "atan2",
]
# Some ternary-like constructs aren't standard; keep to unary/binary.


def _rand_const(rng: random.Random) -> str:
    # Mix small integers, large/small floats, negatives, and special-looking values
    choices = [
        0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5,
        3.14159265, -3.14159265, 2.71828183,
        1e-6, -1e-6, 1e6, -1e6,
    ]
    if rng.random() < 0.5:
        v = rng.choice(choices)
    else:
        # random float with biased magnitude
        sign = -1.0 if rng.random() < 0.3 else 1.0
        mag = 10 ** rng.uniform(-6, 6)
        v = sign * rng.uniform(0, 1) * mag
    # Format conservatively to avoid locale issues
    return f"{v:.10g}"


def _rand_var(rng: random.Random) -> str:
    # libfive uses (var) for a free variable in many text frontends
    # To diversify, sometimes tag vars with indexes by nesting operations
    if rng.random() < 0.7:
        return "(var)"
    # Compose a simple transform around var so the loader still parses a tree
    wraps = [
        lambda s: f"(abs {s})",
        lambda s: f"(neg {s})",
        lambda s: f"(+ {s} 1)",
        lambda s: f"(* 0.5 {s})",
    ]
    return rng.choice(wraps)("(var)")


def _leaf(rng: random.Random) -> str:
    t = rng.random()
    if t < 0.34:
        return rng.choice(COORDS)
    elif t < 0.67:
        return _rand_const(rng)
    else:
        return _rand_var(rng)


def _make_unary(rng: random.Random, depth: int) -> str:
    op = rng.choice(UNARY_OPS)
    arg = _make_expr(rng, depth + 1)
    # special-case neg as unary minus for variety
    if op == "neg":
        return f"(neg {arg})"
    return f"({op} {arg})"


def _make_binary(rng: random.Random, depth: int) -> str:
    op = rng.choice(BINARY_OPS)
    a = _make_expr(rng, depth + 1)
    b = _make_expr(rng, depth + 1)
    return f"({op} {a} {b})"


def _make_nary_sum(rng: random.Random, depth: int) -> str:
    # Build (+ a b c d) to exercise n-ary parsing if supported
    n = rng.randint(3, 5)
    parts = [_make_expr(rng, depth + 1) for _ in range(n)]
    return "(+ " + " ".join(parts) + ")"


def _make_mix(rng: random.Random, depth: int) -> str:
    # Compose a coordinate remap-like structure: e.g., (+ (sin x) (* y z))
    left = _make_unary(rng, depth + 1)
    right = _make_binary(rng, depth + 1)
    if rng.random() < 0.5:
        return f"(+ {left} {right})"
    else:
        return f"(max {left} {right})"


def _make_expr(rng: random.Random, depth: int) -> str:
    # Limit depth to keep size reasonable
    if depth > 5:
        return _leaf(rng)
    p = rng.random()
    if p < 0.25:
        return _leaf(rng)
    elif p < 0.50:
        return _make_unary(rng, depth)
    elif p < 0.80:
        return _make_binary(rng, depth)
    elif p < 0.92:
        return _make_nary_sum(rng, depth)
    else:
        return _make_mix(rng, depth)


def _make_top(rng: random.Random) -> str:
    # Occasionally build a nested let-like composition by combining multiple subtrees
    # Though libfive may not support let, we can emulate via arithmetic composition
    exprs = []
    k = rng.randint(1, 3)
    for _ in range(k):
        exprs.append(_make_expr(rng, 0))
    if len(exprs) == 1:
        return exprs[0]
    # Combine multiple via a balanced min/max or sum
    if rng.random() < 0.5:
        return "(min " + " ".join(exprs) + ")"
    else:
        return "(+ " + " ".join(exprs) + ")"


def _sanitize(s: str, max_len: int = 4000) -> str:
    # Ensure size under cap and add trailing newline. If too long, simplify by reducing whitespace
    if len(s) > max_len:
        s = s[:max_len]
    if not s.endswith("\n"):
        s += "\n"
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly decide whether to produce a single tree or a list of trees (some loaders accept one tree per file)
    multi = rng.random() < 0.2
    pieces: List[str] = []
    count = 1 if not multi else rng.randint(2, 4)
    for _ in range(count):
        pieces.append(_make_top(rng))
    text = "\n".join(pieces)
    text = _sanitize(text, max_len=4000)
    return text.encode("utf-8")
